import heapq

def topological_order_ui_100830(dependencies: Mapping[str, Set[str]]) -> list[str]:
    nodes = set(dependencies)
    for required in dependencies.values():
        nodes.update(required)
    indegree = {node: 0 for node in nodes}
    dependents: dict[str, set[str]] = {node: set() for node in nodes}
    for node, required in dependencies.items():
        indegree[node] += len(required)
        for parent in required:
            dependents[parent].add(node)
    ready = [node for node, degree in indegree.items() if degree == 0]
    heapq.heapify(ready)
    result: list[str] = []
    while ready:
        node = heapq.heappop(ready)
        result.append(node)
        for child in sorted(dependents[node]):
            indegree[child] -= 1
            if indegree[child] == 0:
                heapq.heappush(ready, child)
    if len(result) != len(nodes):
        raise ValueError("dependency cycle")
    return result
